-- Dados fictícios de demonstração do serviço de conta.
-- Execute somente em banco de desenvolvimento/demonstração:
--   python -m backend.services.shared.migrate conta --seed-demo --confirm-demo-database
-- Ids de outros serviços (usuários, categorias, vídeos) são fixos e iguais aos dos seeds desses serviços.

SELECT
    '40000000-0000-4000-8000-000000000001',
    '10000000-0000-4000-8000-000000000001',
    id,
    'pix',
    'pendente_pagamento'
FROM planos WHERE codigo = 'pro'
ON CONFLICT (id) DO UPDATE SET
    atleta_id = EXCLUDED.atleta_id,
    plano_id = EXCLUDED.plano_id,
    metodo_pagamento = EXCLUDED.metodo_pagamento,
    situacao = EXCLUDED.situacao,
    data_atualizacao = now();

ON CONFLICT DO NOTHING;

VALUES ('50000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000001', 'Minha trilha de demonstração', 'privada')
ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, privacidade = EXCLUDED.privacidade, data_atualizacao = now();

ON CONFLICT DO NOTHING;

VALUES ('50000000-0000-4000-8000-000000000001', '20000000-0000-4000-8000-000000000001', 650, FALSE)
ON CONFLICT (trilha_id, video_id) DO UPDATE SET
    segundos_assistidos = EXCLUDED.segundos_assistidos,
    concluido = EXCLUDED.concluido,
    data_atualizacao = now();

-- Mais dados de demonstração: trilhas públicas, progresso e assinaturas.
ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, privacidade = EXCLUDED.privacidade, data_atualizacao = now();

ON CONFLICT DO NOTHING;

ON CONFLICT (trilha_id, video_id) DO NOTHING;

SELECT '40000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000006', id, 'cartao', 'ativa', now() - interval '10 days', now() + interval '20 days' FROM planos WHERE codigo = 'basico'
ON CONFLICT (id) DO NOTHING;
ON CONFLICT DO NOTHING;

SELECT '40000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000007', id, 'pix', 'ativa', now() - interval '10 days', now() + interval '20 days' FROM planos WHERE codigo = 'pro'
ON CONFLICT (id) DO NOTHING;
ON CONFLICT DO NOTHING;

SELECT '40000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000013', id, 'cartao', 'ativa', now() - interval '10 days', now() + interval '20 days' FROM planos WHERE codigo = 'premium'
ON CONFLICT (id) DO NOTHING;
ON CONFLICT DO NOTHING;

SELECT '40000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000014', id, 'boleto', 'pendente_pagamento', NULL, NULL FROM planos WHERE codigo = 'basico'
ON CONFLICT (id) DO NOTHING;
ON CONFLICT DO NOTHING;

